import {
  Button,
  Dialog,
  DialogActions,
  DialogBody,
  DialogContent,
  DialogSurface,
  DialogTitle,
  DialogTrigger,
  Input,
  Label,
  makeStyles,
  tokens,
} from '@fluentui/react-components'
import { useState } from 'react'
import { useCreateBoard } from '../../hooks/useCreateBoard'

const useStyles = makeStyles({
  field: {
    display: 'flex',
    flexDirection: 'column',
    gap: tokens.spacingVerticalXS,
  },
})

export default function CreateBoardDialog() {
  const styles = useStyles()
  const [open, setOpen] = useState(false)
  const [name, setName] = useState('')
  const { mutate, isPending } = useCreateBoard()

  const handleSubmit = () => {
    const trimmed = name.trim()
    if (!trimmed) return
    mutate(
      { name: trimmed },
      {
        onSuccess: () => {
          setName('')
          setOpen(false)
        },
      },
    )
  }

  return (
    <Dialog open={open} onOpenChange={(_, d) => setOpen(d.open)}>
      <DialogTrigger disableButtonEnhancement>
        <Button appearance="primary" aria-label="Create board">
          Create Board
        </Button>
      </DialogTrigger>
      <DialogSurface>
        <DialogBody>
          <DialogTitle>Create Board</DialogTitle>
          <DialogContent>
            <div className={styles.field}>
              <Label htmlFor="board-name">Board name</Label>
              <Input
                id="board-name"
                aria-label="Board name"
                value={name}
                onChange={(_, d) => setName(d.value)}
                onKeyDown={(e) => { if (e.key === 'Enter') handleSubmit() }}
              />
            </div>
          </DialogContent>
          <DialogActions>
            <Button
              appearance="primary"
              disabled={!name.trim() || isPending}
              onClick={handleSubmit}
            >
              Create
            </Button>
            <DialogTrigger disableButtonEnhancement>
              <Button appearance="secondary">Cancel</Button>
            </DialogTrigger>
          </DialogActions>
        </DialogBody>
      </DialogSurface>
    </Dialog>
  )
}

import { FluentProvider, Spinner, Title1, makeStyles, tokens, webLightTheme } from '@fluentui/react-components'
import { useParams } from 'react-router-dom'
import { useBoard } from '../hooks/useBoard'
import { useCurrentUser } from '../hooks/useCurrentUser'
import { useCreateLane } from '../hooks/useCreateLane'
import { useDeleteLane } from '../hooks/useDeleteLane'
import { useRenameLane } from '../hooks/useRenameLane'
import Lane from '../components/board/Lane'
import AddLaneForm from '../components/board/AddLaneForm'

const useStyles = makeStyles({
  root: {
    padding: tokens.spacingHorizontalXXL,
    overflowX: 'auto',
  },
  header: {
    marginBottom: tokens.spacingVerticalL,
  },
  lanes: {
    display: 'flex',
    gap: tokens.spacingHorizontalM,
    alignItems: 'flex-start',
    overflowX: 'auto',
    paddingBottom: tokens.spacingVerticalM,
  },
})

export default function BoardPage() {
  const styles = useStyles()
  const { boardId } = useParams<{ boardId: string }>()
  const { data: board, isPending } = useBoard(boardId ?? '')
  const { user } = useCurrentUser()
  const createLaneMutation = useCreateLane()
  const deleteLaneMutation = useDeleteLane()
  const _renameLaneMutation = useRenameLane()

  const handleAddLane = (bId: string, name: string) => {
    createLaneMutation.mutate({ boardId: bId, name })
  }

  const handleDeleteLane = (bId: string, laneId: string) => {
    deleteLaneMutation.mutate({ boardId: bId, laneId })
  }

  if (isPending) return <Spinner label="Loading board…" />

  if (!board) return null

  const sortedLanes = [...board.lanes].sort((a, b) => a.position - b.position)

  return (
    <FluentProvider theme={webLightTheme}>
      <div className={styles.root}>
        <div className={styles.header}>
          <Title1 as="h1">{board.name}</Title1>
        </div>
        <div className={styles.lanes}>
          {sortedLanes.map((lane) => (
            <Lane
              key={lane.id}
              lane={lane}
              callerRole={board.callerRole}
              onDelete={handleDeleteLane}
            />
          ))}
        </div>
        {(board.callerRole === 'Owner' || board.callerRole === 'Member' || user?.systemRole === 'admin') && (
          <AddLaneForm
            boardId={board.id}
            onAdd={handleAddLane}
            isPending={createLaneMutation.isPending}
          />
        )}
      </div>
    </FluentProvider>
  )
}

